const image=f=>'./media/luz/'+f;
const opening={id:'00',background:'LUZ_00_FONDO_PORTADA.webp',character:'LUZ_00_PERSONAJE_PORTADA.webp',audio:'LUZ_00_PRESENTACION.mp3',intro:[DATA.presentation]};
