 function beforeNavigate(next,path,{restore=false}={}){if(dirty()&&!confirm('Hay una nota sin guardar. ¿Quieres descartarla y salir?'))return false;dirty=()=>false;voice?.dispose();voice=null;if(next==='luz'&&path?.startsWith('notas/')&&!context.startsWith('notas/'))noteReturn=context;if(!restore&&next==='luz'&&path?.startsWith('ruta/')&&context.startsWith('escena/')){state=null;states.delete(path.slice(5));}if(next==='inicio'){state=null;states.clear();}stopAudio();return true;}
 function top(back='inicio'){return append(el('nav',null,{class:'lz-top','aria-label':'Navegación de Luz'}),back==='inicio'?baseLink('← Volver','inicio'):link('← Volver',back,{class:'lz-button lz-secondary'}),append(baseLink('Aquí contigo','apoyo'),icon('people')),baseLink('Inicio','inicio'));}
